package com.rpb.reservation.workforce.calendar.annual;
import static com.rpb.reservation.workforce.calendar.annual.HolidayDtos.*;
import com.rpb.reservation.workforce.calendar.*;import com.rpb.reservation.workforce.application.*;import com.rpb.reservation.workforce.scheduling.SchedulingRepository;
import com.rpb.reservation.workforce.domain.WorkforceException;import com.rpb.reservation.walkin.api.CurrentActor;import java.time.*;import java.util.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly=true)
public class StoreRestMonthService {
 private final WorkforceAccess access;private final CalendarRepository repository;private final CalendarService calendar;private final SchedulingRepository locks;private final WorkforceJson json;
 public StoreRestMonthService(WorkforceAccess access,CalendarRepository repository,CalendarService calendar,SchedulingRepository locks,WorkforceJson json){this.access=access;this.repository=repository;this.calendar=calendar;this.locks=locks;this.json=json;}
 private String hash(String value){try{return java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(java.security.NoSuchAlgorithmException e){throw new IllegalStateException(e);}}
 private YearMonth month(String value){try{var m=YearMonth.parse(value);if(m.getYear()<2000||m.getYear()>2100)throw WorkforceException.invalid();return m;}catch(DateTimeException|NullPointerException e){throw WorkforceException.invalid();}}
 private List<CalendarDtos.CalendarEvent> rows(UUID tenant,UUID store,YearMonth month){return repository.list(tenant,store,month.atDay(1),month.atEndOfMonth()).stream().filter(e->e.kind().equals("store_rest")).toList();}
 public MonthPage get(CurrentActor actor,UUID store,String value){access.enter(actor,store);access.manage(actor,store);var month=month(value);var rows=rows(actor.tenantId(),store,month);return new MonthPage(value,rows.stream().filter(e->e.enabled()).map(CalendarDtos.CalendarEvent::date).sorted().toList(),hash(json.write(rows)));}
 @Transactional public MonthPage save(CurrentActor actor,UUID store,String value,MonthWrite c){access.sourceWrite(actor);access.enter(actor,store);access.manage(actor,store);var month=month(value);if(c==null||c.fingerprint()==null||!c.fingerprint().matches("[a-f0-9]{64}")||c.dates()==null||c.dates().size()>31||c.dates().stream().anyMatch(d->d==null||!YearMonth.from(d).equals(month)))throw WorkforceException.invalid();var dates=c.dates().stream().distinct().sorted().toList();locks.lock("workforce.calendar:"+actor.tenantId()+":"+store);var old=get(actor,store,value);if(old.dates().equals(dates))return old;if(!old.fingerprint().equals(c.fingerprint()))throw WorkforceException.conflict();var rows=rows(actor.tenantId(),store,month);for(var row:rows)if(row.enabled()!=dates.contains(row.date()))calendar.save(actor,store,row.id(),new CalendarDtos.CalendarWrite(row.version(),row.date(),row.kind(),row.name(),dates.contains(row.date())));for(var date:dates)if(rows.stream().noneMatch(r->r.date().equals(date)))calendar.save(actor,store,UUID.randomUUID(),new CalendarDtos.CalendarWrite(0L,date,"store_rest","店休",true));return get(actor,store,value);}
}
